 if($r==='compras'){$u=user();$m=new Tienda();if($method==='POST'&&$a==='finalizar')out(['id_compra'=>$m->comprar((int)$u['sub'])],201);if($method==='GET'&&$a==='todas'){admin($u);out(['compras'=>$m->compras((int)$u['sub'])]);}if($method==='GET')out(['compras'=>$m->compras((int)$u['sub'])]);}
